style.css:
@-moz-document regexp("https?://.*") {
/* ========== DESIGN TOKENS ========== */
  :root {
    /* Base */
    --bg-pure: #000000;
    --bg-deep: #050508;
    --bg-charcoal: #0c0c10;
    --bg-soft: #121218;
    --bg-elevated: #18181f;

    /* Glass */
    --glass-bg: rgba(12, 12, 16, 0.55);
    --glass-bg-strong: rgba(8, 8, 12, 0.72);
    --glass-border: rgba(255, 255, 255, 0.06);
    --glass-border-hover: rgba(255, 255, 255, 0.12);
    --glass-blur: blur(24px) saturate(160%);

    /* Accents - elegant muted */
    --accent-crimson: #9b2335;
    --accent-crimson-soft: #c23a4b;
    --accent-violet: #6b5b95;
    --accent-violet-soft: #8a7bb0;
    --accent-cyan: #3a9ea0;
    --accent-cyan-soft: #5bc4c6;

    /* Text */
    --text-primary: #e8e8ed;
    --text-secondary: #a0a0b0;
    --text-muted: #6b6b7a;

    /* Glow */
    --glow-crimson: 0 0 18px rgba(155, 35, 53, 0.35);
    --glow-violet: 0 0 18px rgba(107, 91, 149, 0.35);
    --glow-cyan: 0 0 18px rgba(58, 158, 160, 0.3);
    --glow-soft: 0 4px 30px rgba(0, 0, 0, 0.5);

    /* Radius */
    --radius-sm: 10px;
    --radius-md: 16px;
    --radius-lg: 22px;
  }

  /* ========== GLOBAL RESET & BASE ========== */
  html {
    background: var(--bg-pure) !important;
    color-scheme: dark only !important;
  }

  body {
    background: var(--bg-deep) !important;
    color: var(--text-primary) !important;
    font-family: "Inter", "Segoe UI", system-ui, -apple-system, sans-serif !important;
    line-height: 1.6 !important;
    -webkit-font-smoothing: antialiased !important;
  }

  /* ========== ANIMATED BACKGROUND ========== */
  body::before {
    content: "" !important;
    position: fixed !important;
    inset: 0 !important;
    z-index: -2 !important;
    background: 
      radial-gradient(ellipse 120% 80% at 20% 30%, rgba(107, 91, 149, 0.12) 0%, transparent 50%),
      radial-gradient(ellipse 100% 70% at 80% 70%, rgba(155, 35, 53, 0.09) 0%, transparent 50%),
      radial-gradient(ellipse 80% 60% at 50% 100%, rgba(58, 158, 160, 0.07) 0%, transparent 50%),
      linear-gradient(180deg, #050508 0%, #0a0a0f 40%, #050508 100%) !important;
    animation: nebulaDrift 45s ease-in-out infinite alternate !important;
  }

  body::after {
    content: "" !important;
    position: fixed !important;
    inset: 0 !important;
    z-index: -1 !important;
    background-image: 
      radial-gradient(1.5px 1.5px at 20px 30px, rgba(255,255,255,0.15), transparent),
      radial-gradient(1.5px 1.5px at 40px 70px, rgba(255,255,255,0.1), transparent),
      radial-gradient(1px 1px at 90px 40px, rgba(255,255,255,0.12), transparent),
      radial-gradient(1.5px 1.5px at 130px 80px, rgba(255,255,255,0.08), transparent),
      radial-gradient(1px 1px at 160px 30px, rgba(255,255,255,0.1), transparent) !important;
    background-size: 200px 100px !important;
    animation: particleFloat 60s linear infinite !important;
    opacity: 0.6 !important;
    pointer-events: none !important;
  }

  @keyframes nebulaDrift {
    0% {
      background-position: 0% 0%, 100% 100%, 50% 100%, 0% 0%;
      filter: brightness(1);
    }
    50% {
      background-position: 30% 20%, 70% 60%, 40% 80%, 0% 0%;
      filter: brightness(1.05);
    }
    100% {
      background-position: 10% 40%, 90% 30%, 60% 70%, 0% 0%;
      filter: brightness(0.98);
    }
  }

  @keyframes particleFloat {
    from { transform: translateY(0); }
    to { transform: translateY(-100px); }
  }

  /* ========== GLASSMORPHISM CORE ========== */
  /* Cards, panels, modals, sidebars, headers */
  [class*="card"],
  [class*="panel"],
  [class*="modal"],
  [class*="dialog"],
  [class*="popup"],
  [class*="dropdown"],
  [class*="menu"],
  [class*="sidebar"],
  [class*="header"],
  [class*="nav"],
  [class*="toolbar"],
  [class*="container"],
  [class*="box"],
  [class*="wrapper"],
  article,
  section,
  aside,
  main > div {
    background: var(--glass-bg) !important;
    backdrop-filter: var(--glass-blur) !important;
    -webkit-backdrop-filter: var(--glass-blur) !important;
    border: 1px solid var(--glass-border) !important;
    border-radius: var(--radius-md) !important;
    box-shadow: var(--glow-soft) !important;
  }

  /* Stronger glass for important surfaces */
  header,
  nav,
  [class*="navbar"],
  [class*="topbar"],
  [class*="app-bar"] {
    background: var(--glass-bg-strong) !important;
    backdrop-filter: blur(28px) saturate(170%) !important;
    -webkit-backdrop-filter: blur(28px) saturate(170%) !important;
    border-bottom: 1px solid var(--glass-border) !important;
    box-shadow: 0 4px 30px rgba(0, 0, 0, 0.4) !important;
  }

  /* ========== TEXT & LINKS ========== */
  h1, h2, h3, h4, h5, h6 {
    color: var(--text-primary) !important;
    font-weight: 600 !important;
    letter-spacing: -0.02em !important;
  }

  p, span, li, label, td, th {
    color: var(--text-secondary) !important;
  }

  a {
    color: var(--accent-cyan-soft) !important;
    text-decoration: none !important;
    transition: color 0.25s ease, text-shadow 0.25s ease !important;
  }

  a:hover {
    color: var(--accent-cyan) !important;
    text-shadow: 0 0 12px rgba(58, 158, 160, 0.4) !important;
  }

  /* ========== BUTTONS ========== */
  button,
  [role="button"],
  input[type="submit"],
  input[type="button"],
  .btn,
  [class*="button"] {
    background: linear-gradient(135deg, rgba(155, 35, 53, 0.25), rgba(107, 91, 149, 0.25)) !important;
    color: var(--text-primary) !important;
    border: 1px solid rgba(155, 35, 53, 0.4) !important;
    border-radius: var(--radius-sm) !important;
    padding: 0.6em 1.4em !important;
    font-weight: 500 !important;
    letter-spacing: 0.02em !important;
    box-shadow: var(--glow-crimson) !important;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1) !important;
    backdrop-filter: blur(12px) !important;
  }

  button:hover,
  [role="button"]:hover,
  .btn:hover {
    background: linear-gradient(135deg, rgba(155, 35, 53, 0.4), rgba(107, 91, 149, 0.35)) !important;
    border-color: var(--accent-crimson-soft) !important;
    box-shadow: 0 0 25px rgba(155, 35, 53, 0.5), 0 0 15px rgba(107, 91, 149, 0.3) !important;
    transform: translateY(-1px) !important;
  }

  /* Secondary / ghost buttons */
  button.secondary,
  .btn-secondary,
  [class*="ghost"] {
    background: transparent !important;
    border: 1px solid var(--glass-border-hover) !important;
    box-shadow: none !important;
  }

  button.secondary:hover {
    background: rgba(255, 255, 255, 0.05) !important;
    border-color: var(--accent-violet-soft) !important;
    box-shadow: var(--glow-violet) !important;
  }

  /* ========== INPUTS ========== */
  input,
  textarea,
  select {
    background: rgba(0, 0, 0, 0.45) !important;
    color: var(--text-primary) !important;
    border: 1px solid var(--glass-border) !important;
    border-radius: var(--radius-sm) !important;
    padding: 0.7em 1em !important;
    transition: border-color 0.25s ease, box-shadow 0.25s ease !important;
  }

  input:focus,
  textarea:focus,
  select:focus {
    outline: none !important;
    border-color: var(--accent-cyan) !important;
    box-shadow: 0 0 0 3px rgba(58, 158, 160, 0.2), var(--glow-cyan) !important;
  }

  /* ========== SCROLLBAR ========== */
  ::-webkit-scrollbar {
    width: 10px !important;
    height: 10px !important;
  }

  ::-webkit-scrollbar-track {
    background: var(--bg-deep) !important;
  }

  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, var(--accent-violet), var(--accent-crimson)) !important;
    border-radius: 10px !important;
    border: 2px solid var(--bg-deep) !important;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, var(--accent-violet-soft), var(--accent-crimson-soft)) !important;
  }

  /* ========== SELECTION ========== */
  ::selection {
    background: rgba(155, 35, 53, 0.45) !important;
    color: #fff !important;
  }

  /* ========== IMAGES & MEDIA ========== */
  img, video {
    border-radius: var(--radius-sm) !important;
    transition: filter 0.3s ease !important;
  }

  img:hover {
    filter: brightness(1.05) !important;
  }

  /* ========== TABLES ========== */
  table {
    background: var(--glass-bg) !important;
    border-collapse: separate !important;
    border-spacing: 0 !important;
    border-radius: var(--radius-md) !important;
    overflow: hidden !important;
    border: 1px solid var(--glass-border) !important;
  }

  th {
    background: rgba(0, 0, 0, 0.4) !important;
    color: var(--text-primary) !important;
    font-weight: 600 !important;
  }

  td {
    border-top: 1px solid var(--glass-border) !important;
  }

  tr:hover td {
    background: rgba(255, 255, 255, 0.03) !important;
  }

  /* ========== HOVER ELEVATION ========== */
  [class*="card"]:hover,
  [class*="panel"]:hover,
  article:hover {
    border-color: var(--glass-border-hover) !important;
    box-shadow: 0 8px 40px rgba(0, 0, 0, 0.55), 0 0 20px rgba(107, 91, 149, 0.15) !important;
    transform: translateY(-2px) !important;
    transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1) !important;
  }

  /* ========== CODE BLOCKS ========== */
  pre, code {
    background: rgba(0, 0, 0, 0.6) !important;
    border: 1px solid var(--glass-border) !important;
    border-radius: var(--radius-sm) !important;
    color: var(--accent-cyan-soft) !important;
  }

  /* ========== FINAL POLISH ========== */
  * {
    border-color: var(--glass-border) !important;
  }

  /* Force dark mode feel on stubborn elements */
  [style*="background: white"],
  [style*="background:#fff"],
  [style*="background: #fff"],
  [style*="background-color: white"],
  [style*="background-color:#fff"] {
    background: var(--bg-elevated) !important;
  }
}
